	private static void installNativeProof(Path live, byte[] proof) throws Exception {
		AtomicBoolean written = new AtomicBoolean();
		try (TripleStore triples = new TripleStore(live.resolve("triples").toFile(),
				new StoreProperties(live.toFile()), config(true), null)) {
			triples.beforePhysicalCommitForTest = () -> {
				try (MemoryStack stack = MemoryStack.stackPush()) {
					var database = stack.mallocInt(1);
					assertEquals(MDB_SUCCESS,
							mdb_dbi_open(triples.writeTxn, TripleStore.NAMESPACE_DATABASE_NAME, 0, database));
					MDBVal key = MDBVal.malloc(stack).mv_data(stack.bytes(KEY));
					MDBVal value = MDBVal.malloc(stack).mv_data(stack.bytes(proof));
					assertEquals(MDB_SUCCESS, mdb_put(triples.writeTxn, database.get(0), key, value, 0));
					written.set(true);
				}
			};
			triples.commitNamespaceSnapshot(Map.of("ack-fixture", "urn:ack-fixture:"),
					triples.prepareReplayDecision(), false);
		}
		assertTrue(written.get(), "The malformed fixture must be committed through a real native transaction");
	}

	private static void writeFileAcknowledgement(Path live, UUID identity, long transaction) throws Exception {
		Path file = live.resolve(PostCommitBackupPublisher.DIRECTORY).resolve("published");
		try (DataOutputStream output = new DataOutputStream(Files.newOutputStream(file))) {
			output.writeInt(0x52344F31);
			output.writeLong(identity.getMostSignificantBits());
			output.writeLong(identity.getLeastSignificantBits());
			output.writeLong(transaction);
		}
		PostCommitBackupPublisher.forceFile(file);
		StoreProperties.forceParentDirectory(file.getParent());
	}

	private static byte[] encoded(UUID identity, long transaction) {
		return ByteBuffer.allocate(Integer.BYTES + 3 * Long.BYTES)
				.putInt(MAGIC)
				.putLong(identity.getMostSignificantBits())
				.putLong(identity.getLeastSignificantBits())
				.putLong(transaction)
				.array();
	}

	private static UUID other(UUID identity) {
		UUID other = new UUID(identity.getMostSignificantBits() ^ 1L, identity.getLeastSignificantBits());
		assertNotEquals(identity, other);
		return other;
	}

	private static String causeMessages(Throwable failure) {
		StringBuilder messages = new StringBuilder();
		for (Throwable current = failure; current != null; current = current.getCause()) {
			messages.append(current.getMessage()).append('\n');
		}
		return messages.toString();
	}

	private static LmdbStoreConfig config(boolean enabled) {
		return new LmdbStoreConfig().setBackupJournalEnabled(enabled);
	}

	private static void add(LmdbStore store, String name) {
		var values = SimpleValueFactory.getInstance();
		try (var connection = store.getConnection()) {
			connection.begin();
			connection.addStatement(values.createIRI("urn:ack-validation:" + name),
					values.createIRI("urn:ack-validation:p"), values.createLiteral(name));
			connection.commit();
		}
	}

	private record Fixture(Path live, Path backups, BackupResult full, UUID firstIdentity, UUID currentIdentity) {
	}
